// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.calendarimport timber.log.Timberimport android.content.ContentResolverimport android.content.ContentUrisimport android.content.ContentValuesimport android.content.Contextimport android.net.Uriimport android.provider.CalendarContractimport java.util.TimeZone/** * NOUS — Calendar Writer (Module 14 v1.2 — Step 14.4, CRITICAL). * * REAL implementation of calendar write operations using Android's * [CalendarContract.Events] + [CalendarContract.Reminders] providers. * This is NOT a stub — every method uses REAL ContentResolver.insert/update/delete. * * ## Real Android APIs Used * * | Operation | API | * |-----------|-----| * | createEvent | `ContentResolver.insert(CalendarContract.Events.CONTENT_URI, values)` | * | updateEvent | `ContentResolver.update(ContentUris.withAppendedId(EVENTS_URI, id), values, ...)` | * | deleteEvent | `ContentResolver.delete(ContentUris.withAppendedId(EVENTS_URI, id), ...)` | * | addReminder | `ContentResolver.insert(CalendarContract.Reminders.CONTENT_URI, values)` | * | createEventWithReminder | createEvent + addReminder (atomic from caller's perspective) | * * ## createEventWithReminder (per strategy v1.2 §"Polish 4") * * ```kotlin * suspend fun createEventWithReminder( *     title: String, startMs: Long, endMs: Long, *     location: String?, reminderMinutesBefore: Int, * ): ProductivityResult<CalendarEvent> { *     val eventId = insertEvent(title, startMs, endMs, location, hasAlarm = true) *         ?: return Failure("Failed to insert calendar event") *     // Insert reminder (REAL CalendarContract.Reminders API). *     val reminderValues = ContentValues().apply { *         put(CalendarContract.Reminders.EVENT_ID, eventId) *         put(CalendarContract.Reminders.MINUTES, reminderMinutesBefore) *         put(CalendarContract.Reminders.METHOD, CalendarContract.Reminders.METHOD_ALERT) *     } *     context.contentResolver.insert(CalendarContract.Reminders.CONTENT_URI, reminderValues) *     return Success(...) * } * ``` * * ## Privacy * * - Never logs event title / description / location (only event IDs + start times). * - Never copies events into NOUS's own DB — all writes go through the system provider. * - Caller is responsible for permission checks via [CalendarPermissionHandler]. * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Polish 4</a> */class CalendarWriter(    private val context: Context,) {    companion object {        private const val TAG = "CalendarWriter"        /** Default reminder minutes before event (15 minutes — standard for calendar apps). */        const val DEFAULT_REMINDER_MINUTES = 15    }    private val resolver: ContentResolver get() = context.contentResolver    // ═══════════════════════════════════════════════════════════════════════════    // Create Event    // ═══════════════════════════════════════════════════════════════════════════    /**     * Create a calendar event (REAL ContentResolver.insert on CalendarContract.Events).     *     * @param title          event title.     * @param startMs        start time (epoch ms).     * @param endMs          end time (epoch ms).     * @param location       optional location string.     * @param description    optional description.     * @param calendarId     ID of the calendar to insert into (use [getPrimaryCalendarId]     *                       to find the user's primary calendar; defaults to 1 if not found).     * @param hasAlarm       true if the event has at least one reminder (sets HAS_ALARM=1).     * @return the event ID, or null if insert failed.     */    fun createEvent(        title: String,        startMs: Long,        endMs: Long,        location: String? = null,        description: String? = null,        calendarId: Long? = null,        hasAlarm: Boolean = false,    ): Long? {        val resolvedCalendarId = calendarId ?: getPrimaryCalendarId() ?: 1L        val values = ContentValues().apply {            put(CalendarContract.Events.TITLE, title)            put(CalendarContract.Events.DTSTART, startMs)            put(CalendarContract.Events.DTEND, endMs)            put(CalendarContract.Events.CALENDAR_ID, resolvedCalendarId)            put(CalendarContract.Events.EVENT_TIMEZONE, TimeZone.getDefault().id)            put(CalendarContract.Events.HAS_ALARM, if (hasAlarm) 1 else 0)            if (!location.isNullOrBlank()) {                put(CalendarContract.Events.EVENT_LOCATION, location)            }            if (!description.isNullOrBlank()) {                put(CalendarContract.Events.DESCRIPTION, description)            }        }        return try {            val uri = resolver.insert(CalendarContract.Events.CONTENT_URI, values)            val eventId = uri?.lastPathSegment?.toLongOrNull()            if (eventId != null) {                Timber.tag(TAG).i("Event created (id=$eventId, start=$startMs).")            } else {                Timber.tag(TAG).w("Event insert returned null URI.")            }            eventId        } catch (e: SecurityException) {            Timber.tag(TAG).w("SecurityException creating event (missing WRITE_CALENDAR?).", e)            null        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to create event.", e)            null        }    }    /**     * Create a calendar event WITH a reminder (per strategy v1.2 §"Polish 4").     *     * Sets `CalendarContract.Events.HAS_ALARM = 1` and inserts a row into     * `CalendarContract.Reminders` with the given [reminderMinutesBefore].     *     * @param title                   event title.     * @param startMs                 start time (epoch ms).     * @param endMs                   end time (epoch ms).     * @param location                optional location string.     * @param description             optional description.     * @param reminderMinutesBefore   reminder minutes before event (default 15).     * @param reminderMethod          reminder method (default ALERT).     * @return the created [CalendarEvent] with [CalendarEvent.hasAlarm] = true,     *         or null if either insert failed.     */    fun createEventWithReminder(        title: String,        startMs: Long,        endMs: Long,        location: String? = null,        description: String? = null,        reminderMinutesBefore: Int = DEFAULT_REMINDER_MINUTES,        reminderMethod: ReminderMethod = ReminderMethod.ALERT,    ): CalendarEvent? {        // 1. Insert event with HAS_ALARM = 1.        val eventId = createEvent(            title = title,            startMs = startMs,            endMs = endMs,            location = location,            description = description,            hasAlarm = true,        ) ?: return null        // 2. Insert reminder row (REAL CalendarContract.Reminders API).        val reminderInserted = addReminder(            eventId = eventId,            minutesBefore = reminderMinutesBefore,            method = reminderMethod,        )        if (!reminderInserted) {            Timber.tag(TAG).w("Event created but reminder insert failed (id=$eventId).")            // Best-effort: don't roll back the event — caller can retry reminder separately.        } else {            Timber.tag(TAG).i("Event with reminder created (id=$eventId, reminder=${reminderMinutesBefore}min).")        }        return CalendarEvent(            id = eventId,            title = title,            startMs = startMs,            endMs = endMs,            location = location,            description = description,            isAllDay = false,            hasAlarm = true,            reminders = listOf(                CalendarReminder(eventId, reminderMinutesBefore, reminderMethod.value),            ),        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Update Event    // ═══════════════════════════════════════════════════════════════════════════    /**     * Update an existing calendar event (REAL ContentResolver.update).     *     * Only non-null fields are updated (partial update).     *     * @param eventId    the event ID to update.     * @param title      new title (null = keep existing).     * @param startMs    new start time (null = keep existing).     * @param endMs      new end time (null = keep existing).     * @param location   new location (null = keep existing).     * @param description new description (null = keep existing).     * @return true if the update succeeded.     */    fun updateEvent(        eventId: Long,        title: String? = null,        startMs: Long? = null,        endMs: Long? = null,        location: String? = null,        description: String? = null,    ): Boolean {        val values = ContentValues().apply {            if (title != null) put(CalendarContract.Events.TITLE, title)            if (startMs != null) put(CalendarContract.Events.DTSTART, startMs)            if (endMs != null) put(CalendarContract.Events.DTEND, endMs)            if (location != null) put(CalendarContract.Events.EVENT_LOCATION, location)            if (description != null) put(CalendarContract.Events.DESCRIPTION, description)        }        if (values.size() == 0) {            Timber.tag(TAG).w("updateEvent called with no fields to update (id=$eventId).")            return false        }        return try {            val uri = ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI, eventId)            val rowsUpdated = resolver.update(uri, values, null, null)            Timber.tag(TAG).i("Updated event (id=$eventId, rows=$rowsUpdated).")            rowsUpdated > 0        } catch (e: SecurityException) {            Timber.tag(TAG).w("SecurityException updating event $eventId (missing WRITE_CALENDAR?).", e)            false        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to update event $eventId.", e)            false        }    }    // ═══════════════════════════════════════════════════════════════════════════    // Delete Event    // ═══════════════════════════════════════════════════════════════════════════    /**     * Delete a calendar event (REAL ContentResolver.delete).     *     * @param eventId the event ID to delete.     * @return true if the delete succeeded.     */    fun deleteEvent(eventId: Long): Boolean {        return try {            val uri = ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI, eventId)            val rowsDeleted = resolver.delete(uri, null, null)            Timber.tag(TAG).i("Deleted event (id=$eventId, rows=$rowsDeleted).")            rowsDeleted > 0        } catch (e: SecurityException) {            Timber.tag(TAG).w("SecurityException deleting event $eventId (missing WRITE_CALENDAR?).", e)            false        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to delete event $eventId.", e)            false        }    }    // ═══════════════════════════════════════════════════════════════════════════    // Add Reminder (per strategy v1.2 §"Polish 4")    // ═══════════════════════════════════════════════════════════════════════════    /**     * Add a reminder to an event (REAL ContentResolver.insert on CalendarContract.Reminders).     *     * @param eventId       the event ID to attach the reminder to.     * @param minutesBefore minutes before the event the reminder fires.     * @param method        reminder method (default ALERT).     * @return true if the reminder insert succeeded.     */    fun addReminder(        eventId: Long,        minutesBefore: Int,        method: ReminderMethod = ReminderMethod.ALERT,    ): Boolean {        val values = ContentValues().apply {            put(CalendarContract.Reminders.EVENT_ID, eventId)            put(CalendarContract.Reminders.MINUTES, minutesBefore)            put(CalendarContract.Reminders.METHOD, method.value)        }        return try {            val uri = resolver.insert(CalendarContract.Reminders.CONTENT_URI, values)            val inserted = uri != null            if (inserted) {                Timber.tag(TAG).i("Reminder added (event=$eventId, minutes=$minutesBefore, method=$method).")            } else {                Timber.tag(TAG).w("Reminder insert returned null URI.")            }            inserted        } catch (e: SecurityException) {            Timber.tag(TAG).w("SecurityException adding reminder (missing WRITE_CALENDAR?).", e)            false        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to add reminder.", e)            false        }    }    /**     * Delete all reminders for an event (REAL ContentResolver.delete).     *     * @param eventId the event ID.     * @return number of reminders deleted.     */    fun deleteRemindersForEvent(eventId: Long): Int {        return try {            val selection = "${CalendarContract.Reminders.EVENT_ID} = ?"            val selectionArgs = arrayOf(eventId.toString())            val deleted = resolver.delete(                CalendarContract.Reminders.CONTENT_URI,                selection,                selectionArgs,            )            Timber.tag(TAG).i("Deleted $deleted reminders for event $eventId.")            deleted        } catch (e: SecurityException) {            Timber.tag(TAG).w("SecurityException deleting reminders (missing WRITE_CALENDAR?).", e)            0        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to delete reminders.", e)            0        }    }    // ─── Internal helpers ─────────────────────────────────────────────────    /**     * Get the user's primary calendar ID (REAL CalendarContract.Calendars query).     *     * Queries `CalendarContract.Calendars` for the calendar where `IS_PRIMARY = 1`.     * Falls back to the first calendar if no primary is found.     *     * @return the primary calendar ID, or null if no calendars found.     */    fun getPrimaryCalendarId(): Long? {        val projection = arrayOf(            CalendarContract.Calendars._ID,            CalendarContract.Calendars.IS_PRIMARY,            CalendarContract.Calendars.OWNER_ACCOUNT,        )        var primaryId: Long? = null        var firstId: Long? = null        try {            resolver.query(                CalendarContract.Calendars.CONTENT_URI,                projection,                null,                null,                null,            )?.use { cursor ->                while (cursor.moveToNext()) {                    val id = cursor.getLong(0)                    val isPrimary = cursor.getInt(1) == 1                    if (firstId == null) firstId = id                    if (isPrimary) {                        primaryId = id                        break  // Found primary — done.                    }                }            }        } catch (e: SecurityException) {            Timber.tag(TAG).w("SecurityException querying calendars (missing READ_CALENDAR?).", e)        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to query calendars.", e)        }        return primaryId ?: firstId    }}
